package com.example.handler;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.Serializable;
import java.util.Base64;
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;

@Path("/api/v1/transform")
public class DataTransformHandler {

    private static final ObjectMapper mapper = new ObjectMapper();

    // Internal type registry for polymorphic deserialization
    interface DataPayload extends Serializable {
        String getType();
        Object getValue();
    }

    static class StringPayload implements DataPayload {
        private String value;
        public StringPayload(String v) { this.value = v; }
        public String getType() { return "string"; }
        public Object getValue() { return value; }
    }

    static class NumericPayload implements DataPayload {
        private Number value;
        public NumericPayload(Number v) { this.value = v; }
        public String getType() { return "numeric"; }
        public Object getValue() { return value; }
    }

    @POST
    @Path("/process")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response processTransform(String body) {
        try {
            JsonNode root = mapper.readTree(body);
            String encoding = root.has("encoding") ? root.get("encoding").asText() : "json";

            Object result;

            if ("native".equals(encoding)) {
                // Legacy support: accept pre-serialized Java objects from trusted internal services
                String serializedData = root.get("data").asText();
                byte[] rawBytes = Base64.getDecoder().decode(serializedData);
                ByteArrayInputStream bais = new ByteArrayInputStream(rawBytes);
                ObjectInputStream ois = new ObjectInputStream(bais);
                // Type check: ensure deserialized object implements our interface
                Object deserialized = ois.readObject();
                if (!(deserialized instanceof DataPayload)) {
                    return Response.status(400)
                        .entity("{\"error\": \"Type mismatch: expected DataPayload\"}")
                        .build();
                }
                DataPayload payload = (DataPayload) deserialized;
                result = payload.getValue();
            } else {
                // Standard JSON path
                JsonNode dataNode = root.get("data");
                if (dataNode == null) {
                    return Response.status(400)
                        .entity("{\"error\": \"Missing data field\"}")
                        .build();
                }
                result = dataNode.asText();
            }

            ObjectNode response = mapper.createObjectNode();
            response.put("status", "processed");
            response.put("result", String.valueOf(result));
            response.put("resultType", result.getClass().getSimpleName());

            return Response.ok(response.toString()).build();

        } catch (Exception e) {
            return Response.status(500)
                .entity("{\"error\": \"" + e.getMessage() + "\"}")
                .build();
        }
    }

    @POST
    @Path("/health")
    @Produces(MediaType.APPLICATION_JSON)
    public Response healthCheck() {
        ObjectNode status = mapper.createObjectNode();
        status.put("status", "UP");
        status.put("handler", "DataTransformHandler");
        status.put("capabilities", "json,native");
        return Response.ok(status.toString()).build();
    }
}
